import{_ as o,c as t,o as r,a2 as i}from"./chunks/framework.mqLGQ42V.js";const f=JSON.parse('{"title":"导出为运行时文件 (Exporting for Runtime) - Rive 编辑器","description":"导出 (Exporting) 导出为运行时文件功能仅在付费计划中提供。","frontmatter":{"title":"导出为运行时文件 (Exporting for Runtime) - Rive 编辑器","description":"导出 (Exporting) 导出为运行时文件功能仅在付费计划中提供。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 导出, 导出为运行时文件"}]]},"headers":[],"relativePath":"editor/exporting/exporting-for-runtime.md","filePath":"editor/exporting/exporting-for-runtime.md","lastUpdated":1774867914000}'),a={name:"editor/exporting/exporting-for-runtime.md"};function n(p,e,d,c,s,l){return r(),t("div",null,[...e[0]||(e[0]=[i('<p>导出 (Exporting)</p><h1 id="导出为运行时文件-exporting-for-runtime" tabindex="-1">导出为运行时文件 (Exporting for Runtime) <a class="header-anchor" href="#导出为运行时文件-exporting-for-runtime" aria-label="Permalink to &quot;导出为运行时文件 (Exporting for Runtime)&quot;">​</a></h1><p>导出为运行时文件功能仅在付费计划中提供。</p><p>要导出适用于运行时的文件，请选择工具栏右侧的蓝色导出图标，或通过左侧菜单导航至 <code>Export</code> &gt; <code>For runtime</code>。你可以将导出的 <code>.riv</code> 文件加载到你的应用、游戏或网站中，通过我们的任何<a href="/docs/runtimes/overview">开源运行时库</a>进行调用。</p><h2 id="​-导出对象名称的变更" tabindex="-1"><a href="#changes-to-exporting-object-names">​</a> 导出对象名称的变更 <a class="header-anchor" href="#​-导出对象名称的变更" aria-label="Permalink to &quot;[​](#changes-to-exporting-object-names) 导出对象名称的变更&quot;">​</a></h2><p>你可能需要在运行时访问某些对象，例如通过文本串替换字符串，或者通过组件访问其输入。为了让这些对象在运行时可被搜索到，你需要显式地将其名称设置为“导出”。</p><p>在以前，只要你在编辑器中重命名了对象（非默认名），它的名称就会被导出。但这种方式假设了所有重命名的对象都需要在运行时被访问，而实际上很多时候重命名只是为了整理文件。因此，我们更改了这一做法，以提供更精细的控制。</p><p><strong>如何导出名称</strong>： 在层级面板或舞台上右键点击对象，勾选 <strong>“Export name (导出名称)”</strong> 选项。</p><p>被设置为导出名称的对象在层级面板中会被括号 <code>[]</code> 包裹。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 导出名称示例 Pn)</p></blockquote><p><em>注意：动画、状态机、事件和输入名称不需要手动操作即可导出。</em></p><h2 id="​-优化名称的好处" tabindex="-1"><a href="#benefits-of-optimizing-your-names">​</a> 优化名称的好处 <a class="header-anchor" href="#​-优化名称的好处" aria-label="Permalink to &quot;[​](#benefits-of-optimizing-your-names) 优化名称的好处&quot;">​</a></h2><p>导出对象名称会增加 <code>.riv</code> 文件的一点点体积。对于大型复杂文件，累积的名称数据可能会影响性能。因此，建议仅导出需要在代码中引用的名称。</p><h2 id="​-在引入显式导出前创建的文件策略" tabindex="-1"><a href="#files-created-before-the-introduction-of-explicit-export">​</a> 在引入显式导出前创建的文件策略 <a class="header-anchor" href="#​-在引入显式导出前创建的文件策略" aria-label="Permalink to &quot;[​](#files-created-before-the-introduction-of-explicit-export) 在引入显式导出前创建的文件策略&quot;">​</a></h2><p>对于在此功能实施前创建的文件，我们默认假设所有重命名的对象都需要在运行时可发现。如果你想清理这些导出的名称以减小文件体积，可以：</p><ol><li>从工具栏菜单选择 <code>Export options</code> &gt; <code>Remove name exports</code>。</li><li>针对需要在运行时访问的对象，手动重新勾选 <code>Export name</code>。</li></ol><p><a href="/docs/editor/keyboard-shortcuts">键盘快捷键 (Keyboard Shortcuts)</a><a href="https://help.rive.app/editor/exporting/exporting-for-video-and-static-design" target="_blank" rel="noreferrer">导出视频或静态图</a></p>',17)])])}const h=o(a,[["render",n]]);export{f as __pageData,h as default};
